  const v = field(R, o, 'v'); const h0 = own(R, s, 'hand'), e0 = own(R, s, 'evid'); attack(R, c, v); finishContact(R); ok(own(R, s, 'hand') >= h0 + 1 && own(R, s, 'evid') > e0, '액션 시 드로우+증거');
  const R2 = mk(defs, ['c'], ['v'], 'blue'); const s2 = R2.turn, o2 = 1 - s2; const c2 = field(R2, s2, 'c'); const v2 = field(R2, o2, 'v'); R2.cards[c2].under = []; ok(!FX.hasKwTk(R2, c2, 'assault'), '0장: 突撃 없음');
  R2.cards[c2].under = U.filler(R2, s2, 1); eq(asK(R2, c2), 'plain', '1장: 突撃'); let h = own(R2, s2, 'hand'), e = own(R2, s2, 'evid'); attack(R2, c2, v2); finishContact(R2); eq(own(R2, s2, 'hand'), h, '1장: 드로우 없음'); eq(own(R2, s2, 'evid'), e, '1장: 증거 없음');
