t('id_0704', '파트너(黄) 선언(턴1,슬립): 상대 증거 1개 덱 아래 → 상대 AP8000 이하 캐릭터를 상대가 앞면 증거로 / 대상이 MR 이면 상대는 덱 위 1장도 앞면 증거로', () => {
  const run = (pc = 'yellow') => { const R = mk({ c: rc('id_0704'), a: dm('A', { ap: '8000' }), b: dm('B', { ap: '9000' }), mr: dm('MRC', { ap: '5000', ab: [{ ic: 'mr' }] }), e0: dm('HIDDENE'), e1: dm('UPE') }, ['c'], ['a'], pc, 'yellow'); const s = R.turn, o = 1 - s; const c = field(R, s, 'c'); const a = field(R, o, 'a'), b = field(R, o, 'b'); const e0 = evBot(R, o, 'e0'), e1 = evAt(R, o, 'e1', true); return { R, s, o, c, a, b, e0, e1 }; };
  let r = run(); decl(r.R, r.s, r.c); eq(r.R.cards[r.c].st, 's', '슬립'); let q = req(r.R); eq(q.kind, 'opt', '증거 선택'); ok(!optLabels(r.R).includes('HIDDENE') && optLabels(r.R).includes('UPE'), '뒷면 증거 이름 비공개'); ok(req(r.R).evp && req(r.R).evp.pos.length === 2, '증거가 개별 선택지(evp)'); ans(r.R, optLabels(r.R).split(' | ').findIndex(l => l.includes('UPE'))); ok(r.R.P[r.o].deck[0] === r.e1, '앞면 증거가 상대 덱 맨 아래'); ok(!r.R.cards[r.e1].up, '덱으로 가면 뒷면'); q = req(r.R); ok(q.sel.includes(r.a) && !q.sel.includes(r.b) && !q.sel.includes(r.c), 'AP8000 이하 상대 캐릭터'); rej(r.R, [r.b]); rej(r.R, [r.c]); ans(r.R, [r.a]); pump(r.R); ok(has(r.R, r.o, 'evid', r.a) && r.R.cards[r.a].up, '상대가 앞면 증거로'); ok(!ctxLog(r.R).includes('HIDDENE'), '로그에 뒷면 증거 이름 없음');
  const R2 = mk({ c: rc('id_0704'), mr: dm('MRC', { ap: '5000', ab: [{ ic: 'mr' }] }), z: dm('Z') }, ['c'], ['z'], 'yellow'); const s2 = R2.turn, o2 = 1 - s2; const c2 = field(R2, s2, 'c'); const mr = field(R2, o2, 'mr'); field(R2, o2, 'z'); const dk0 = own(R2, o2, 'deck'); const ev0 = own(R2, o2, 'evid'); decl(R2, s2, c2); if (req(R2) && req(R2).kind === 'opt') ans(R2, req(R2).labels.length - 1); ans(R2, [mr]); pump(R2);
  ok(has(R2, o2, 'pa', mr) && !has(R2, o2, 'evid', mr), 'MR: 내 턴(=MR 소유자의 상대 턴)에 현장을 떠나므로 증거가 아니라 파트너 에리어로'); eq(own(R2, o2, 'deck'), dk0 - 1, 'MR 대상: 상대 덱 위 1장'); const top = R2.P[o2].evid[R2.P[o2].evid.length - 1]; ok(R2.cards[top].up && !R2.cards[top].d.includes('mr'), '덱 위 카드가 앞면 증거로');
  r = run('blue'); ok(chk(r.R, r.s, r.c), '파트너 黄 아님: 불가'); r = run(); decl(r.R, r.s, r.c); ans(r.R, 0); ans(r.R, [r.a]); pump(r.R); r.R.cards[r.c].st = 'a'; ok(declErr(r.R, r.s, r.c), '턴 1회'); });
t('id_0704', '히라메키: 증거에서 리무브될 때 캐릭터 1장까지 슬립', () => {
  const R = mk({ c: rc('id_0704'), a: dm('A'), x: dm('X') }, ['c'], ['a'], 'yellow'); const s = R.turn, o = 1 - s; evAt(R, s, 'c'); const a = field(R, o, 'a'), x = field(R, s, 'x'); caseHit(R, o, a); ans(R, true); const q = req(R); ok(q.sel.includes(a) && q.sel.includes(x)); ans(R, [a]); pump(R); eq(R.cards[a].st, 's', '슬립'); });
t('id_0705', '突撃 / 액션 시: 내 뒷면 증거 1개 + 상대 뒷면 증거 1개를 앞면으로(가능하면 필수) → 합쳐 2개면 AP+1000(턴 종료 시 해제)', () => {
  const run = (me, op) => { const R = mk({ c: rc('id_0705'), v: dm('V', { ap: '500' }) }, ['c'], ['v'], 'yellow'); const s = R.turn, o = 1 - s; const c = field(R, s, 'c'); const v = field(R, o, 'v', 's'); const mev = U.evid(R, s, me), oev = U.evid(R, o, op); const ap0 = S.ap(R, c); attack(R, c, v); finishContact(R); U.fpAuto(R); return { R, s, o, c, mev, oev, ap0 }; };
  const nup = (R, ids) => ids.filter(x => R.cards[x].up).length;
  let r = run(2, 2); eq(nup(r.R, r.mev), 1, '내 증거 1개 앞면'); eq(nup(r.R, r.oev), 1, '상대 증거 1개 앞면'); ok(!r.R.eff, '질의 없이 처리(필수)'); eq(S.ap(r.R, r.c), r.ap0 + 1000, '합쳐 2개: AP+1000'); endTurn(r.R); auto(r.R); eq(S.ap(r.R, r.c), r.ap0, '턴 종료 시 해제');
  r = run(0, 2); eq(nup(r.R, r.oev), 1, '내 증거 없음: 상대 것만'); eq(S.ap(r.R, r.c), r.ap0, 'AP 그대로'); r = run(2, 0); eq(nup(r.R, r.mev), 1, '상대 증거 없음: 내 것만'); eq(S.ap(r.R, r.c), r.ap0, 'AP 그대로');
  const R = mk({ c: rc('id_0705') }, ['c'], ['c'], 'yellow'); ok(FX.hasKwTk(R, field(R, R.turn, 'c'), 'assault'), '突撃'); });
t('id_0705', '히라메키: 상대의 뒷면 증거 1개까지 앞면으로', () => {
  const R = mk({ c: rc('id_0705'), a: dm('A') }, ['c'], ['a'], 'yellow'); const s = R.turn, o = 1 - s; evAt(R, s, 'c'); const a = field(R, o, 'a'); const oev = U.evid(R, o, 2); caseHit(R, o, a); ans(R, true); pump(R); eq(R.P[o].evid.filter(x => R.cards[x].up).length, 1, '상대 뒷면 증거 1개 앞면(상대는 케이스 액션으로 방금 얻은 증거가 아님)'); });
t('id_0735', '내 손패의 【青】 카드는 컷인 AP+1000 을 가짐(상대·다른 색은 아님)', () => {
  const run = (own_, col, withC = true) => { const R = mk({ c: rc('id_0735'), a: dm('A'), ba: dm('BA', { color: col }), v: dm('V', { ap: '1000' }) }, ['c', 'ba'], ['ba', 'v'], 'blue'); const s = R.turn, o = 1 - s; if (withC) field(R, s, 'c'); const a = field(R, s, 'a'), v = field(R, o, 'v'); const ba = own_ ? hand(R, s, 'ba') : hand(R, o, 'ba'); attack(R, v, a); return { R, s, o, a, ba, v }; };
  let r = run(true, 'blue'); const ap0 = S.ap(r.R, r.a); eq(act(r.R, r.R.sub.who === r.s ? r.s : r.s, { a: 'cin', id: r.ba }), undefined, '컷인 사용'); pump(r.R); eq(S.ap(r.R, r.a), ap0 + 1000, 'AP+1000');
  r = run(true, 'blue', false); ok(typeof act(r.R, r.s, { a: 'cin', id: r.ba }) === 'string', '이 캐릭터가 없으면 컷인 불가'); r = run(true, 'red'); ok(typeof act(r.R, r.s, { a: 'cin', id: r.ba }) === 'string', '【青】 이 아니면 불가'); r = run(false, 'blue'); ok(typeof act(r.R, r.o, { a: 'cin', id: r.ba }) === 'string' || r.R.sub.who !== r.o, '상대의 【青】 카드는 해당 없음'); });
t('id_0735', '파트너(青) 등장 시: 상대 Lv8 이하 캐릭터 1장 + 상대 리무브 에리어의 같은 이름 캐릭터 1장을 상대가 순서를 정해 덱 아래로', () => {
  const run = pc => { const R = mk({ c: rc('id_0735'), a: dm('NA', { lv: '8' }), b: dm('NB', { lv: '9' }), a2: dm('NA', { lv: '3' }), z: dm('NZ'), a3: dm('NA', { lv: '1' }) }, ['c'], ['a'], pc, 'blue'); const s = R.turn, o = 1 - s; const a = field(R, o, 'a'), b = field(R, o, 'b'); const a2 = rem(R, o, 'a2'), z = rem(R, o, 'z'), a3 = rem(R, o, 'a3'); return { R, s, o, a, b, a2, z, a3, c: hand(R, s, 'c') }; };
  let r = run('blue'); play(r.R, r.s, r.c); let q = req(r.R); ok(q.kind === 'pick' && q.sel.includes(r.a) && !q.sel.includes(r.b), 'Lv8 이하 상대 캐릭터'); rej(r.R, [r.b]); ans(r.R, [r.a]); q = req(r.R); ok(q.kind === 'pick' && !q.ordered && q.sel.includes(r.a2) && q.sel.includes(r.a3) && !q.sel.includes(r.z), '같은 이름 캐릭터만'); rej(r.R, [r.z]); ans(r.R, [r.a2]); q = req(r.R); ok(q && q.ordered && q.who === r.o, '상대가 순서 지정'); ok(q.ids.includes(r.a) && q.ids.includes(r.a2), '두 장'); ans(r.R, [r.a2, r.a]); pump(r.R);
  ok(!has(r.R, r.o, 'field', r.a) && !has(r.R, r.o, 'rem', r.a2), '두 장 모두 이동'); ok(r.R.P[r.o].deck[0] === r.a && r.R.P[r.o].deck[1] === r.a2, '상대가 정한 순서로 덱 아래'); ok(has(r.R, r.o, 'rem', r.a3), '선택하지 않은 카드는 그대로');
  r = run('red'); play(r.R, r.s, r.c); ok(!req(r.R), '파트너 青 아님: 발동 안 함'); });
t('id_0746', '세트: 【青】 캐릭터만 / 세트된 캐릭터는 突撃[キャラ] + 선언(턴1): 내 리무브 에리어의 캐릭터 1장까지를 덱 위로', () => {
  const R = mk({ e: rc('id_0746'), a: dm('A', { color: 'blue' }), a2: dm('A2', { color: 'blue' }), rr: dm('RR', { color: 'red' }), r1: dm('R1'), r2: dm('R2'), ev: EVD('EVX', 'blue', []) }, ['e'], ['e'], 'blue'); const s = R.turn; const a = field(R, s, 'a'), a2 = field(R, s, 'a2'), rr = field(R, s, 'rr'); const e = hand(R, s, 'e'); const r1 = rem(R, s, 'r1'), r2 = rem(R, s, 'r2'), evc = rem(R, s, 'ev');
  play(R, s, e); let q = req(R); ok(q.sel.includes(a) && q.sel.includes(a2) && !q.sel.includes(rr), '【青】 캐릭터만'); rej(R, [rr]); ans(R, [a]); pump(R); ok(R.cards[a].sets.includes(e), '세트됨'); ok(FX.hasKwTk(R, a, 'assault-char') && !FX.hasKwTk(R, a2, 'assault-char'), '突撃[キャラ]');
  const acts = S.actsFor(R, s)[a] || []; const ab = acts.find(x => x.k === 'abil' || x.k === 'decl' || x.i != null); ok(ab, '선언 능력이 행동 목록에 있음 ' + JSON.stringify(acts).slice(0, 200));
  const e1 = FX.declare(R, s, a, ab.i); ok(!e1, e1); pump(R); q = req(R); ok(q.kind === 'pick' && q.sel.includes(r1) && q.sel.includes(r2) && !q.sel.includes(evc), '리무브 에리어의 캐릭터만'); rej(R, [evc]); ans(R, [r1]); pump(R); eq(R.P[s].deck[R.P[s].deck.length - 1], r1, '덱 맨 위'); ok(!has(R, s, 'rem', r1), '리무브 에리어에서 빠짐'); ok(FX.declare(R, s, a, ab.i), '턴 1회'); });
t('id_0760', '등장 시: 내 덱 위 1장을 뒷면으로 이 캐릭터에 세트', () => {
  const R = mk({ c: rc('id_0760') }, ['c'], ['c'], 'yellow'); const s = R.turn; const c = hand(R, s, 'c'); const d0 = own(R, s, 'deck'); play(R, s, c); ok(!req(R), '질의 없음'); eq(nfd(R, c), 1, '뒷면 세트'); eq(own(R, s, 'deck'), d0 - 1, '덱 -1'); const sl = S.view(R, 1 - s).P[s].field.find(x => x.id === c).sl; ok(sl[0].hidden && !sl[0].d, '상대 화면: 비공개'); });
t('id_0760', '【事件赤魔術】 선언(슬립+손패 1장 리무브): 캐릭터 1장까지 리무브 → 내 캐릭터의 뒷면 세트 카드 합쳐 2장 리무브해도 됨 → 리무브 에리어의 Lv3 이하 【白】 캐릭터 1장 등장', () => {
  const run = (kt = '赤魔術', yes = true) => { const R = mkB({ c: rc('id_0760'), a: dm('A'), v: dm('V'), w1: dm('W1', { color: 'white', lv: '3' }), w2: dm('W2', { color: 'white', lv: '4' }), w3: dm('W3', { color: 'red', lv: '2' }) }, ['c'], ['v'], 'yellow', { n: 'K', type: 'case', color: 'yellow', lv: '2', lv2: '3', trait: kt }); const s = R.turn, o = 1 - s; const c = field(R, s, 'c'), a = field(R, s, 'a'), v = field(R, o, 'v'); const f1 = fdSet(R, c), f2 = fdSet(R, a); const w1 = rem(R, s, 'w1'), w2 = rem(R, s, 'w2'), w3 = rem(R, s, 'w3'); return { R, s, o, c, a, v, f1, f2, w1, w2, w3 }; };
  let r = run(); eq(chk(r.R, r.s, r.c), '', '선언 가능'); decl(r.R, r.s, r.c); let q = req(r.R); eq(q.kind, 'pick', '코스트: 손패 1장'); const h0 = own(r.R, r.s, 'hand'); ans(r.R, [q.sel[0]]); eq(own(r.R, r.s, 'hand'), h0 - 1, '손패 -1'); eq(r.R.cards[r.c].st, 's', '슬립'); q = req(r.R); ok(q.sel.includes(r.v) && q.sel.includes(r.a), '캐릭터 선택'); ans(r.R, [r.v]); q = req(r.R); eq(q.kind, 'yn', '세트 카드 2장 리무브 여부'); ans(r.R, true);
  q = req(r.R); if (q && q.kind === 'pick' && !q.sel.includes(r.w1)) { ok(q.sel.includes(r.c) && q.sel.includes(r.a), '내 캐릭터의 세트'); ans(r.R, [r.c]); } q = req(r.R); ok(q && q.kind === 'pick' && q.sel.includes(r.w1) && q.sel.includes(r.w2) === false && !q.sel.includes(r.w3), 'Lv3 이하 【白】 만'); rej(r.R, [r.w2]); rej(r.R, [r.w3]); ans(r.R, [r.w1]); pump(r.R);
  ok(has(r.R, r.o, 'rem', r.v), '캐릭터 리무브'); ok(has(r.R, r.s, 'rem', r.f1) && has(r.R, r.s, 'rem', r.f2), '세트 카드 2장 리무브'); ok(has(r.R, r.s, 'field', r.w1), '등장');
  r = run(); decl(r.R, r.s, r.c); ans(r.R, [req(r.R).sel[0]]); ans(r.R, [r.v]); ans(r.R, false); pump(r.R); ok(!req(r.R), '거절: 끝'); ok(has(r.R, r.o, 'rem', r.v), '캐릭터는 이미 리무브'); eq(nfd(r.R, r.c) + nfd(r.R, r.a), 2, '세트 유지'); ok(!has(r.R, r.s, 'field', r.w1), '등장 없음');
  r = run('高校生'); ok(chk(r.R, r.s, r.c), '사건이 赤魔術 아님: 선언 불가'); });
t('id_0787', '【事件赤魔術】 내 리무브 에리어의 Lv3 이하 【白】 캐릭터 1장 등장 + AP+3000 + 突撃[キャラ](턴 종료 시 해제) + 덱 위 1장을 뒷면으로 그 캐릭터에 세트', () => {
  const run = (kt = '赤魔術') => { const R = mkB({ e: rc('id_0787'), w1: dm('W1', { color: 'white', lv: '3' }), w2: dm('W2', { color: 'white', lv: '2' }), w3: dm('W3', { color: 'white', lv: '4' }), w4: dm('W4', { color: 'red', lv: '1' }) }, ['e'], ['e'], 'white', { n: 'K', type: 'case', color: 'white', lv: '2', lv2: '3', trait: kt }); const s = R.turn; const w1 = rem(R, s, 'w1'), w2 = rem(R, s, 'w2'), w3 = rem(R, s, 'w3'), w4 = rem(R, s, 'w4'); const e = hand(R, s, 'e'); return { R, s, e, w1, w2, w3, w4 }; };
  let r = run(); const d0 = own(r.R, r.s, 'deck'); play(r.R, r.s, r.e); let q = req(r.R); ok(q.sel.includes(r.w1) && q.sel.includes(r.w2) && !q.sel.includes(r.w3) && !q.sel.includes(r.w4), 'Lv3 이하 【白】 만'); rej(r.R, [r.w3]); rej(r.R, [r.w4]); ans(r.R, [r.w1]); pump(r.R); ok(has(r.R, r.s, 'field', r.w1), '등장'); eq(S.ap(r.R, r.w1), 1000 + 3000, 'AP+3000'); ok(FX.hasKwTk(r.R, r.w1, 'assault-char'), '突撃[キャラ]'); eq(nfd(r.R, r.w1), 1, '뒷면 세트'); eq(own(r.R, r.s, 'deck'), d0 - 1, '덱 -1');
  endTurn(r.R); auto(r.R); eq(S.ap(r.R, r.w1), 1000, '턴 종료 시 AP 해제'); ok(!FX.hasKwTk(r.R, r.w1, 'assault-char'), '突撃 해제');
  r = run('高校生'); play(r.R, r.s, r.e); ok(!req(r.R), '사건이 赤魔術 아님: 효과 없음'); });

t('id_0808', '등장 시: Lv7 이하 캐릭터 1장까지 리무브', () => {
  const R = mk({ c: rc('id_0808', { lv: '8' }), a: dm('A', { lv: '7' }), b: dm('B', { lv: '8' }) }, ['c'], ['a'], 'yellow'); const s = R.turn, o = 1 - s; const a = field(R, o, 'a'), b = field(R, o, 'b'); const c = hand(R, s, 'c'); play(R, s, c); const q = req(R); ok(q.sel.includes(a) && !q.sel.includes(b), 'Lv7 이하만'); rej(R, [b]); ans(R, [a]); pump(R); ok(has(R, o, 'rem', a), '리무브');
  const R2 = mk({ c: rc('id_0808', { lv: '8' }), a: dm('A', { lv: '7' }) }, ['c'], ['a'], 'yellow'); const o2 = 1 - R2.turn; const a2 = field(R2, o2, 'a'); play(R2, R2.turn, hand(R2, R2.turn, 'c')); ans(R2, []); ok(has(R2, o2, 'field', a2), '0장 선택 가능'); });
t('id_0808', '파트너(黄)【FILE⑤】 선언(슬립 + 현장의 Lv7 이하 [警視庁] 1장을 덱 아래로): 캐릭터 1장까지 리무브', () => {
  const run = (pc = 'yellow', file = 5) => { const R = mk({ c: rc('id_0808', { lv: '8' }), kp: dm('KK', { trait: '警視庁', lv: '7' }), k8: dm('K8', { trait: '警視庁', lv: '8' }), z: dm('ZZ', { trait: '高校生', lv: '2' }), v: dm('V') }, ['c'], ['v'], pc, 'yellow'); const s = R.turn, o = 1 - s; fileN(R, s, file); const c = field(R, s, 'c'), k = field(R, s, 'kp'), k8 = field(R, s, 'k8'), z = field(R, s, 'z'); const v = field(R, o, 'v'); return { R, s, o, c, k, k8, z, v }; };
  let r = run(); eq(chk(r.R, r.s, r.c, 0), '', '선언 가능'); decl(r.R, r.s, r.c); eq(r.R.cards[r.c].st, 's', '슬립 코스트'); ok(!has(r.R, r.s, 'field', r.k) && r.R.P[r.s].deck[0] === r.k, '[警視庁] Lv7 이하가 덱 아래로(코스트)'); ok(has(r.R, r.s, 'field', r.k8), 'Lv8 [警視庁] 는 코스트 대상 아님'); const q = req(r.R); ok(q.sel.includes(r.v) && q.sel.includes(r.z), '캐릭터 선택'); ans(r.R, [r.v]); pump(r.R); ok(has(r.R, r.o, 'rem', r.v), '리무브');
  r = run('blue'); ok(chk(r.R, r.s, r.c, 0), '파트너 黄 아님: 불가'); r = run('yellow', 4); ok(chk(r.R, r.s, r.c, 0), 'FILE 4장: 불가'); r = run(); r.R.P[r.s].field = r.R.P[r.s].field.filter(x => x !== r.k); ok(chk(r.R, r.s, r.c, 0), '[警視庁] Lv7 이하가 현장에 없으면 불가'); });
t('id_0826', '파트너(黒) 내 턴 이 캐릭터가 내 효과로 리무브되면: 앞면 증거 1개까지 뒷면으로(양쪽 앞면 증거가 대상) / 상대 효과·파트너 黒 아님은 발동 안 함', () => {
  const run = (pc, mine = true) => { const R = mk({ c: rc('id_0826'), x: EVD('X', 'black', [{ op: 'select', n: 1, filter: { own: mine ? 'self' : 'opp' }, do: 'remove' }]), e1: dm('E1'), e2: dm('E2'), e3: dm('E3'), e4: dm('E4') }, ['c', 'x'], ['x'], pc, 'black'); const s = R.turn, o = 1 - s; const c = field(R, s, 'c'); const m1 = evAt(R, s, 'e1', true), m2 = evAt(R, s, 'e2', false), o1 = evAt(R, o, 'e3', true), o2 = evAt(R, o, 'e4', false); const x = hand(R, mine ? s : o, 'x'); R.turn = mine ? s : o; R.fl = {}; play(R, R.turn, x); if (req(R) && req(R).sel && req(R).sel.includes(c)) ans(R, [c]); pump(R); return { R, s, o, c, m1, m2, o1, o2 }; };
  let r = run('black'); ok(!has(r.R, r.s, 'field', r.c), '리무브됨'); let q = req(r.R); ok(q && q.kind === 'pick' && q.sel.includes(r.m1) && q.sel.includes(r.o1) && !q.sel.includes(r.m2) && !q.sel.includes(r.o2), '앞면 증거만(양쪽)'); rej(r.R, [r.m2]); ans(r.R, [r.o1]); pump(r.R); ok(!r.R.cards[r.o1].up, '뒷면으로');
  r = run('black'); ans(r.R, []); ok(r.R.cards[r.m1].up && r.R.cards[r.o1].up, '0장 선택 가능'); r = run('red'); ok(!r.R.eff, '파트너 黒 아님: 발동 안 함'); r = run('black', false); ok(!r.R.eff || !(r.R.eff.req.sel || []).includes(r.m1), '상대 효과로 리무브: 발동 안 함'); });
t('id_0826', '히라메키: 증거에서 리무브될 때 앞면 증거 1개까지 뒷면으로', () => {
  const R = mk({ c: rc('id_0826'), a: dm('A'), e1: dm('E1') }, ['c'], ['a'], 'red'); const s = R.turn, o = 1 - s; evAt(R, s, 'c'); const a = field(R, o, 'a'); const e1 = evBot(R, s, 'e1', true); caseHit(R, o, a); ans(R, true); const q = req(R); ok(q.sel.includes(e1)); ans(R, [e1]); pump(R); ok(!R.cards[e1].up, '뒷면으로'); });
t('id_0827', '파트너(黒) 등장 시: 상대 손패 공개 → 【カットイン】 가진 Lv8 이하 1장까지 상대가 리무브 → 리무브했고 상대 손패가 4장 이하면 상대 1장 드로우', () => {
  const run = (nHand, pc = 'black') => { const R = mk({ c: rc('id_0827'), a: dm('HA', { lv: '3', kw: 'cutin:1000', ab: [{ ic: 'cutin', v: 1000 }] }), b: dm('HB', { lv: '9', kw: 'cutin:1000', ab: [{ ic: 'cutin', v: 1000 }] }), n: dm('HN', { lv: '2' }) }, ['c'], ['a', 'b', 'n'], pc, 'black'); const s = R.turn, o = 1 - s; clearHand(R, o); const a = hand(R, o, 'a'), b = hand(R, o, 'b'), n = hand(R, o, 'n'); for (let i = 3; i < nHand; i++) R.P[o].hand.push(...filler(R, o, 1)); return { R, s, o, a, b, n, c: hand(R, s, 'c') }; };
  let r = run(5); play(r.R, r.s, r.c); let q = req(r.R); eq(q.kind, 'ack', '손패 공개'); eq(q.who, r.s, '내가 확인'); eq(q.ids.length, 5, '5장 전부'); ans(r.R, null); q = req(r.R); ok(q.sel.includes(r.a) && !q.sel.includes(r.b) && !q.sel.includes(r.n), '【カットイン】 Lv8 이하만'); rej(r.R, [r.b]); rej(r.R, [r.n]); ans(r.R, [r.a]); pump(r.R); ok(has(r.R, r.o, 'rem', r.a), '리무브'); eq(own(r.R, r.o, 'hand'), 5, '5-1=4 → 4장 이하: 1장 드로우');
  r = run(6); play(r.R, r.s, r.c); ans(r.R, null); ans(r.R, [r.a]); pump(r.R); eq(own(r.R, r.o, 'hand'), 5, '6-1=5 → 드로우 없음'); r = run(5); play(r.R, r.s, r.c); ans(r.R, null); ans(r.R, []); eq(own(r.R, r.o, 'hand'), 5, '리무브 안 하면 드로우 없음');
  r = run(3, 'red'); play(r.R, r.s, r.c); ok(!req(r.R), '파트너 黒 아님: 발동 안 함'); });
t('id_0840', '내 턴 종료 시 [毛利蘭] 이 내 현장에 없으면 이 캐릭터 리무브(있으면 유지, 상대 턴 종료엔 발동 안 함)', () => {
  const run = (ran, my = true) => { const R = mk({ c: rc('id_0840'), r: dm('毛利蘭') }, ['c'], ['c'], 'blue'); const s = R.turn, o = 1 - s; const c = field(R, s, 'c'); if (ran) field(R, s, 'r'); R.turn = my ? s : o; R.fl = {}; endTurn(R); auto(R); pump(R); return { R, s, c }; };
  let r = run(false); ok(!has(r.R, r.s, 'field', r.c) && has(r.R, r.s, 'rem', r.c), '[毛利蘭] 없음: 리무브'); r = run(true); ok(has(r.R, r.s, 'field', r.c), '[毛利蘭] 있음: 유지'); r = run(false, false); ok(has(r.R, r.s, 'field', r.c), '상대 턴 종료: 발동 안 함'); });
t('id_0840', '파트너(青) 등장 시: AP8000 이하 캐릭터 1장까지 덱 아래로', () => {
  const run = pc => { const R = mk({ c: rc('id_0840'), a: dm('A', { ap: '8000' }), b: dm('B', { ap: '9000' }), m: dm('M', { ap: '1000' }) }, ['c'], ['a'], pc, 'blue'); const s = R.turn, o = 1 - s; const a = field(R, o, 'a'), b = field(R, o, 'b'), m = field(R, s, 'm'); return { R, s, o, a, b, m, c: hand(R, s, 'c') }; };
  let r = run('blue'); play(r.R, r.s, r.c); const q = req(r.R); ok(q.sel.includes(r.a) && q.sel.includes(r.m) && !q.sel.includes(r.b), 'AP8000 이하'); rej(r.R, [r.b]); ans(r.R, [r.a]); pump(r.R); ok(r.R.P[r.o].deck[0] === r.a, '상대 덱 아래'); r = run('red'); play(r.R, r.s, r.c); ok(!req(r.R), '파트너 青 아님: 발동 안 함'); });
t('id_0840', '【事件シャッフルロマンス】 선언(턴1): 내 현장의 [毛利蘭] 1장까지를 이 캐릭터 아래에 겹침 → 겹쳤으면 이번 턴 突撃[キャラ]', () => {
  const run = (kt = 'シャッフルロマンス', ran = 2) => { const R = mkB({ c: rc('id_0840'), r1: dm('毛利蘭'), r2: dm('毛利蘭'), x: dm('X') }, ['c'], ['c'], 'blue', { n: 'K', type: 'case', color: 'blue', lv: '2', lv2: '3', trait: kt }); const s = R.turn; const c = field(R, s, 'c'); const rs = []; for (let i = 1; i <= ran; i++) rs.push(field(R, s, 'r' + i)); const x = field(R, s, 'x'); return { R, s, c, rs, x }; };
  let r = run(); decl(r.R, r.s, r.c); let q = req(r.R); ok(q.sel.includes(r.rs[0]) && q.sel.includes(r.rs[1]) && !q.sel.includes(r.x), '[毛利蘭] 만'); rej(r.R, [r.x]); ans(r.R, [r.rs[0]]); pump(r.R); ok(r.R.cards[r.c].under.includes(r.rs[0]) && !has(r.R, r.s, 'field', r.rs[0]), '아래에 겹침'); ok(FX.hasKwTk(r.R, r.c, 'assault-char'), '突撃[キャラ]'); ok(declErr(r.R, r.s, r.c), '턴 1회'); endTurn(r.R); auto(r.R); ok(!FX.hasKwTk(r.R, r.c, 'assault-char'), '턴 종료 시 해제');
  r = run(); decl(r.R, r.s, r.c); ans(r.R, []); ok(!FX.hasKwTk(r.R, r.c, 'assault-char'), '0장: 突撃 없음'); r = run('他'); ok(chk(r.R, r.s, r.c, 0) !== '' , '사건이 シャッフルロマンス 아님: 불가'); });
t('id_0843', '파트너(青) 선언(턴1): 캐릭터 1장까지 리무브 → 내 덱 위에서 그 캐릭터의 레벨과 같은 장수 리무브', () => {
  const run = pc => { const R = mk({ c: rc('id_0843'), a: dm('A', { lv: '3' }), b: dm('B', { lv: '0' }) }, ['c'], ['a'], pc, 'blue'); const s = R.turn, o = 1 - s; const c = field(R, s, 'c'); const a = field(R, o, 'a'), b = field(R, o, 'b'); return { R, s, o, c, a, b }; };
  let r = run('blue'); const d0 = own(r.R, r.s, 'deck'), m0 = own(r.R, r.s, 'rem'); decl(r.R, r.s, r.c, 0); const q = req(r.R); ok(q.sel.includes(r.a) && q.sel.includes(r.b) && q.sel.includes(r.c), '모든 캐릭터 후보'); ans(r.R, [r.a]); pump(r.R); ok(has(r.R, r.o, 'rem', r.a), '리무브'); eq(own(r.R, r.s, 'deck'), d0 - 3, 'Lv3 → 덱 3장 리무브'); eq(own(r.R, r.s, 'rem'), m0 + 3, '리무브 에리어 +3'); ok(declErr(r.R, r.s, r.c, 0), '턴 1회');
  r = run('blue'); const d00 = own(r.R, r.s, 'deck'); decl(r.R, r.s, r.c, 0); ans(r.R, []); eq(own(r.R, r.s, 'deck'), d00, '리무브 안 하면 덱 변화 없음'); r = run('blue'); const d1 = own(r.R, r.s, 'deck'); decl(r.R, r.s, r.c, 0); ans(r.R, [r.b]); pump(r.R); eq(own(r.R, r.s, 'deck'), d1, 'Lv0: 0장'); r = run('red'); ok(chk(r.R, r.s, r.c, 0), '파트너 青 아님: 불가'); });
t('id_0843', '선언(턴1, 파트너 에리어 가능): 리무브 에리어의 [少年探偵団] 1장까지를 내 현장의 【青】 캐릭터 아래에 겹침', () => {
  [false, true].forEach(inPa => { const R = mk({ c: rc('id_0843'), s1: dm('S1', { trait: '少年探偵団' }), z: dm('Z', { trait: '高校生' }), b1: dm('B1', { color: 'blue' }), r1: dm('R1', { color: 'red' }) }, ['c'], ['c'], 'blue'); const s = R.turn; const c = inPa ? pa(R, s, 'c') : field(R, s, 'c'); const s1 = rem(R, s, 's1'), z = rem(R, s, 'z'); const b1 = field(R, s, 'b1'), r1 = field(R, s, 'r1');
    decl(R, s, c, 1); let q = req(R); ok(q.sel.includes(s1) && !q.sel.includes(z), '[少年探偵団] 만'); rej(R, [z]); ans(R, [s1]); q = req(R); if (q) { ok(q.sel.includes(b1) && !q.sel.includes(r1), '【青】 캐릭터 대상'); rej(R, [r1]); ans(R, [b1]); } else ok(inPa, '파트너 에리어: 현장의 【青】 캐릭터가 1장뿐이면 자동 선택'); pump(R); ok(R.cards[b1].under.includes(s1) && !has(R, s, 'rem', s1), '겹침'); ok(declErr(R, s, c, 1), '턴 1회'); }); });
t('id_0843', '컷인 AP+2000', () => {
  const R = mk({ c: rc('id_0843'), a: dm('A'), v: dm('V', { ap: '1000' }) }, ['c'], ['v'], 'blue'); const s = R.turn, o = 1 - s; const a = field(R, s, 'a'), v = field(R, o, 'v'); const c = hand(R, s, 'c'); attack(R, v, a); const ap0 = S.ap(R, a); act(R, R.sub.who, { a: 'cin', id: c }); pump(R); eq(S.ap(R, a), ap0 + 2000, 'AP+2000'); });
t('id_0847', '선언(슬립): 손패의 [少年探偵団] 1장을 공개해 내 【青】 캐릭터 아래에 겹침 → Lv7 이하 캐릭터 1장까지 리무브', () => {
  const run = () => { const R = mk({ c: rc('id_0847'), s1: dm('S1', { trait: '少年探偵団' }), s2: dm('S2', { trait: '少年探偵団' }), z: dm('Z', { trait: '高校生' }), b1: dm('B1', { color: 'blue' }), r1: dm('R1', { color: 'red' }), a: dm('A', { lv: '7' }), b: dm('B', { lv: '8' }) }, ['c'], ['a'], 'blue'); const s = R.turn, o = 1 - s; const c = field(R, s, 'c'); const s1 = hand(R, s, 's1'), s2 = hand(R, s, 's2'), z = hand(R, s, 'z'); const b1 = field(R, s, 'b1'), r1 = field(R, s, 'r1'); const a = field(R, o, 'a'), b = field(R, o, 'b'); return { R, s, o, c, s1, s2, z, b1, r1, a, b }; };
  let r = run(); decl(r.R, r.s, r.c); eq(r.R.cards[r.c].st, 's', '슬립'); let q = req(r.R); ok(q.kind === 'pick' && q.sel.includes(r.s1) && q.sel.includes(r.s2) && !q.sel.includes(r.z), '[少年探偵団] 만'); rej(r.R, [r.z]); ans(r.R, [r.s1]); q = req(r.R); ok(q.sel.includes(r.b1) && !q.sel.includes(r.r1), '【青】 캐릭터 대상'); rej(r.R, [r.r1]); ans(r.R, [r.b1]); q = req(r.R); eq(q.kind, 'ack', '공개'); eq(q.who, r.o, '상대가 확인'); ok(q.ids[0] === r.s1, '공개 카드'); ans(r.R, null); ok(r.R.cards[r.b1].under.includes(r.s1), '겹침'); q = req(r.R); ok(q.sel.includes(r.a) && !q.sel.includes(r.b), 'Lv7 이하'); rej(r.R, [r.b]); ans(r.R, [r.a]); pump(r.R); ok(has(r.R, r.o, 'rem', r.a), '리무브');
  r = run(); const h = r.R.P[r.s].hand.filter(x => x === r.s1 || x === r.s2); r.R.P[r.s].hand = r.R.P[r.s].hand.filter(x => !h.includes(x)); ok(chk(r.R, r.s, r.c), '[少年探偵団] 손패 없음: 불가'); });
t('id_0847', '히라메키【解決編】: 아크션 중인 캐릭터 1장까지 스턴 / 事件編이면 발동 불가', () => {
  const run = solved => { const R = mkB({ c: rc('id_0847'), a: dm('A'), x: dm('X') }, ['c'], ['a'], 'blue', caseDef('id_0530', { color: 'blue' })); const s = R.turn, o = 1 - s; if (solved) { sol(R, s); auto(R); } evAt(R, s, 'c'); const a = field(R, o, 'a'), x = field(R, o, 'x'); caseHit(R, o, a); return { R, s, o, a, x }; };
  let r = run(true); eq(req(r.R).kind, 'yn', '히라메키 발동 여부'); ans(r.R, true); const q = req(r.R); ok(q.sel.includes(r.a) && !q.sel.includes(r.x), '액션 중인 캐릭터만'); rej(r.R, [r.x]); ans(r.R, [r.a]); pump(r.R); eq(r.R.cards[r.a].st, 'x', '스턴');
  r = run(false); ok(!r.R.eff || r.R.eff.req.kind !== 'pick', '事件編: 효과 없음'); });
t('id_0848', '파트너(青) 突撃[事件] / 내 턴 [겹침 1장 이상]: AP+1000+突撃[キャラ] (상대 턴·0장은 아님)', () => {
  const run = pc => { const R = mk({ c: rc('id_0848') }, ['c'], ['c'], pc, 'blue'); const s = R.turn; const c = field(R, s, 'c'); return { R, s, c }; };
  let r = run('blue'); ok(FX.hasKwTk(r.R, r.c, 'assault-case'), '突撃[事件]'); const base = +U.DB().id_0848.ap; eq(S.ap(r.R, r.c), base, '겹침 0장: AP 그대로'); ok(!FX.hasKwTk(r.R, r.c, 'assault-char'), '겹침 0장: 突撃[キャラ] 없음');
  r.R.cards[r.c].under = U.filler(r.R, r.s, 1); eq(S.ap(r.R, r.c), base + 1000, '1장: AP+1000'); ok(FX.hasKwTk(r.R, r.c, 'assault-char'), '1장: 突撃[キャラ]'); r.R.turn = 1 - r.s; eq(S.ap(r.R, r.c), base, '상대 턴: AP 그대로'); ok(!FX.hasKwTk(r.R, r.c, 'assault-char'), '상대 턴: 突撃 없음');
  r = run('red'); ok(!FX.hasKwTk(r.R, r.c, 'assault-case'), '파트너 青 아님: 突撃[事件] 없음'); });
t('id_0848', '【겹침 3장 이상】【FILE⑤】 선언(턴1): 손패 1장 리무브 → 이 캐릭터를 액티브로', () => {
  const run = (under = 3, file = 5, st = 's') => { const R = mk({ c: rc('id_0848') }, ['c'], ['c'], 'blue'); const s = R.turn; const c = field(R, s, 'c', st); R.cards[c].under = U.filler(R, s, under); fileN(R, s, file); return { R, s, c }; };
  let r = run(); eq(chk(r.R, r.s, r.c), '', '선언 가능'); decl(r.R, r.s, r.c); let q = req(r.R); ok(q.kind === 'pick' && q.min === 1, '손패 1장 리무브(코스트)'); const h0 = own(r.R, r.s, 'hand'); ans(r.R, [q.sel[0]]); pump(r.R); eq(own(r.R, r.s, 'hand'), h0 - 1, '손패 -1'); eq(r.R.cards[r.c].st, 'a', '액티브'); ok(declErr(r.R, r.s, r.c), '턴 1회');
  r = run(2); ok(chk(r.R, r.s, r.c), '겹침 2장: 불가'); r = run(3, 4); ok(chk(r.R, r.s, r.c), 'FILE 4장: 불가'); r = run(); r.R.turn = 1 - r.s; ok(chk(r.R, r.s, r.c), '상대 턴: 불가'); });
t('id_0868', '선언(슬립 + 이 캐릭터 이외의 현장 캐릭터 1장을 리무브 에리어로): 내 뒷면 증거를 원하는 수만큼 앞면 → 같은 수까지 상대 뒷면 증거를 앞면', () => {
  const run = (me, op) => { const R = mk({ c: rc('id_0868'), a: dm('A'), x: dm('X') }, ['c'], ['x'], 'green'); const s = R.turn, o = 1 - s; const c = field(R, s, 'c'), a = field(R, s, 'a'); const mev = U.evid(R, s, me), oev = U.evid(R, o, op); return { R, s, o, c, a, mev, oev }; };
  const nup = (R, ids) => ids.filter(x => R.cards[x].up).length;
  let r = run(3, 2); decl(r.R, r.s, r.c); eq(r.R.cards[r.c].st, 's', '슬립'); ok(has(r.R, r.s, 'rem', r.a) || req(r.R), '코스트: 다른 캐릭터 리무브'); let q = req(r.R); if (q && q.kind === 'pick') { ok(!q.sel.includes(r.c), '이 캐릭터는 코스트 대상 아님'); ans(r.R, [r.a]); } q = req(r.R); eq(q.kind, 'opt', '장수 선택'); eq(q.labels.length, 4, '0~3장'); ans(r.R, 3); q = req(r.R); eq(q.kind, 'opt', '상대 증거 장수(같은 수까지)'); eq(q.labels.length, 3, '0~2장(상대 뒷면 증거 2장)'); ans(r.R, 2); pump(r.R); eq(nup(r.R, r.mev), 3, '내 증거 3장'); eq(nup(r.R, r.oev), 2, '상대는 2장(있는 만큼)');
  r = run(3, 5); decl(r.R, r.s, r.c); if (req(r.R) && req(r.R).kind === 'pick') ans(r.R, [r.a]); ans(r.R, 2); U.fpAuto(r.R); q = req(r.R); eq(q.labels.length, 3, '같은 2장까지'); ans(r.R, 1); pump(r.R); eq(nup(r.R, r.mev), 2, '내 증거 2장'); eq(nup(r.R, r.oev), 1, '상대는 1장(0~2장 중 선택)'); r = run(0, 3); decl(r.R, r.s, r.c); if (req(r.R) && req(r.R).kind === 'pick') ans(r.R, [r.a]); pump(r.R); ok(!req(r.R) || r.R.eff.req.kind !== 'opt', '내 뒷면 증거가 없으면 선택 없음'); eq(nup(r.R, r.oev), 0, '상대 증거 그대로');
  const R = mk({ c: rc('id_0868') }, ['c'], ['c'], 'green'); const c = field(R, R.turn, 'c'); ok(chk(R, R.turn, c), '이 캐릭터 이외의 캐릭터가 없으면 불가'); });
t('id_0868', '히라메키: 1장 드로우', () => {
  const R = mk({ c: rc('id_0868'), a: dm('A') }, ['c'], ['a'], 'green'); const s = R.turn, o = 1 - s; evAt(R, s, 'c'); const a = field(R, o, 'a'); const h0 = own(R, s, 'hand'); caseHit(R, o, a); ans(R, true); pump(R); eq(own(R, s, 'hand'), h0 + 1, '드로우'); });
t('id_0911', '등장 시: 특징을 지정하고 捜査3 → 지정 특징 발견 장수에 따라 1장↑ 突撃[キャラ] / 2장↑ 突撃 / 3장↑ 迅速 (턴 종료 시 해제)', () => {
  const run = (named, traits) => { const defs = { c: rc('id_0911') }; traits.forEach((t, i) => { defs['k' + i] = dm('K' + i, { trait: t }); }); const R = mk(defs, ['c'], ['c'], 'yellow'); const s = R.turn, o = 1 - s; const ids = traits.map((t, i) => top(R, o, 'k' + i)); const c = hand(R, s, 'c'); play(R, s, c); let q = req(R); eq(q.kind, 'text', '특징 지정'); ans(R, named); q = req(R); eq(q.kind, 'ack', '수사 결과'); eq(q.ids.length, 3, '3장'); ans(R, null); q = req(R); eq(q.who, o, '상대가 순서'); ans(R, q.ids); pump(R); return { R, s, o, c, ids }; };
  const kws = (R, c) => [asK(R, c) === 'char' || asK(R, c) === 'plain', asK(R, c) === 'plain', FX.hasKwTk(R, c, 'rapid')];
  let r = run('警察', ['警察', '探偵', '高校生']); eq(kws(r.R, r.c).join(), 'true,false,false', '1장: 突撃[キャラ]'); r = run('警察', ['警察', '警察', '探偵']); eq(kws(r.R, r.c).join(), 'true,true,false', '2장: 突撃'); r = run('警察', ['警察', '警察,公安', '警察']); eq(kws(r.R, r.c).join(), 'true,true,true', '3장: 迅速'); endTurn(r.R); auto(r.R); eq(kws(r.R, r.c).join(), 'false,false,false', '턴 종료 시 해제'); r = run('警察', ['探偵', '探偵', '高校生']); eq(kws(r.R, r.c).join(), 'false,false,false', '0장: 없음');
  const dk = r.R.P[r.o].deck; ok(r.ids.every(x => dk.slice(0, 3).includes(x)), '발견된 카드는 상대 덱 아래'); });
t('id_0942', '액션 시: 캐릭터 1장까지 AP+1000(턴 종료 시 해제) / 등장 시: 상대 현장 3장↑ 突撃[キャラ], 상대 증거 3개↑ 突撃[事件]', () => {
  const run = (nf, ne) => { const defs = { c: rc('id_0942') }; for (let i = 0; i < nf; i++) defs['f' + i] = dm('F' + i); const R = mk(defs, ['c'], ['c'], 'yellow'); const s = R.turn, o = 1 - s; for (let i = 0; i < nf; i++) field(R, o, 'f' + i); U.evid(R, o, ne); const c = hand(R, s, 'c'); play(R, s, c); return { R, s, o, c }; };
  let r = run(3, 3); ok(FX.hasKwTk(r.R, r.c, 'assault-char') && FX.hasKwTk(r.R, r.c, 'assault-case'), '둘 다'); endTurn(r.R); auto(r.R); ok(!FX.hasKwTk(r.R, r.c, 'assault-char') && !FX.hasKwTk(r.R, r.c, 'assault-case'), '턴 종료 시 해제');
  r = run(2, 3); ok(!FX.hasKwTk(r.R, r.c, 'assault-char') && FX.hasKwTk(r.R, r.c, 'assault-case'), '현장 2장: 突撃[キャラ] 없음'); r = run(3, 2); ok(FX.hasKwTk(r.R, r.c, 'assault-char') && !FX.hasKwTk(r.R, r.c, 'assault-case'), '증거 2개: 突撃[事件] 없음');
  const R = mk({ c: rc('id_0942'), v: dm('V', { ap: '100' }), a: dm('A') }, ['c'], ['v'], 'yellow'); const s = R.turn, o = 1 - s; const c = field(R, s, 'c'), a = field(R, s, 'a'); const v = field(R, o, 'v', 's'); attack(R, c, v); const q = req(R); ok(q && q.kind === 'pick' && q.sel.includes(a) && q.sel.includes(c) && q.sel.includes(v), '액션 시 캐릭터 선택'); rej(R, [999999]); const ap0 = S.ap(R, a); ans(R, [a]); eq(S.ap(R, a), ap0 + 1000, 'AP+1000'); finishContact(R); pump(R); endTurn(R); auto(R); eq(S.ap(R, a), ap0, '턴 종료 시 해제'); });
t('id_0948', '내 턴 현장에서 레벨-2 / 상대 턴은 그대로', () => {
  const R = mk({ c: rc('id_0948', { lv: '8' }) }, ['c'], ['c'], 'blue'); const s = R.turn; const c = field(R, s, 'c'); eq(FX.lvOf(R, c), 6, '내 턴: Lv8-2'); R.turn = 1 - s; eq(FX.lvOf(R, c), 8, '상대 턴: Lv8'); const c2 = hand(R, s, 'c'); R.turn = s; });
t('id_0948', '【事件 青&緑】 내 턴(턴1): 이 캐릭터 이외의 Lv7 이하 【青】/【緑】 캐릭터가 내 현장에 등장하면 AP8000 이하 캐릭터 1장까지 리무브 / 다른 색·Lv8 이상·사건 색 불일치·상대 턴은 발동 안 함', () => {
  const run = (bc, over = {}) => { const R = mkB({ c: rc('id_0948', { lv: '8' }), b7: dm('B7', { color: 'blue', lv: '7' }), b8: dm('B8', { color: 'blue', lv: '8' }), g7: dm('G7', { color: 'green', lv: '7' }), g8: dm('G8', { color: 'green', lv: '8' }), r1: dm('R1', { color: 'red', lv: '1' }), a: dm('A', { ap: '8000' }), b: dm('B', { ap: '9000' }) }, ['c', 'b7', 'g7', 'b8', 'g8', 'r1'], ['a'], 'blue', { n: 'K', type: 'case', color: bc === 'blue&green' ? 'blue&green&red' : bc, lv: '2', lv2: '3' }); const s = R.turn, o = 1 - s; const c = field(R, s, 'c'); const a = field(R, o, 'a'), b = field(R, o, 'b'); return { R, s, o, c, a, b }; };
  const enter = (r, k) => { r.R.fl = {}; const id = hand(r.R, r.s, k); play(r.R, r.s, id); return id; };
  let r = run('blue&green'); enter(r, 'b7'); let q = req(r.R); ok(q && q.sel.includes(r.a) && !q.sel.includes(r.b), 'AP8000 이하'); rej(r.R, [r.b]); ans(r.R, [r.a]); pump(r.R); ok(has(r.R, r.o, 'rem', r.a), '리무브'); enter(r, 'g7'); ok(!r.R.eff, '턴 1회: 두 번째는 발동 안 함');
  r = run('blue&green'); enter(r, 'g7'); ok(r.R.eff, '【緑】 Lv7: 발동'); r = run('blue&green'); enter(r, 'g8'); ok(!r.R.eff, '【緑】 Lv8: 발동 안 함(Lv7 이하만)'); r = run('blue&green'); enter(r, 'b8'); ok(!r.R.eff, '【青】 Lv8: 발동 안 함'); r = run('blue&green'); enter(r, 'r1'); ok(!r.R.eff, '다른 색: 발동 안 함');
  r = run('blue'); enter(r, 'b7'); ok(!r.R.eff, '사건이 青&緑 아님: 발동 안 함'); r = run('blue&green'); const bb = field(r.R, r.s, 'b7'); r.R.turn = r.o; r.R.fl = {}; FX.bus(r.R, 'enter', { s: r.s, ent: bb, by: 'effect' }); pump(r.R); ok(!r.R.eff, '상대 턴: 발동 안 함'); r = run('blue&green'); const bb2 = field(r.R, r.o, 'b7'); FX.bus(r.R, 'enter', { s: r.o, ent: bb2, by: 'effect' }); pump(r.R); ok(!r.R.eff, '상대 현장에 등장: 발동 안 함'); });
t('id_0948', '【絆 服部平次】 선언(턴1, 덱 위 1장 리무브): 카드명 지정 → 상대 FILE 위 1장 리무브 + 상대 덱 위 1장을 뒷면으로 FILE 위에 → 지정한 카드명이 리무브되면 캐릭터 1장 AP+2000', () => {
  const run = (named, bond = true) => { const R = mk({ c: rc('id_0948', { lv: '8' }), h: dm('服部平次'), fz: dm('FILETARGET'), fy: dm('FILEOTHER'), a: dm('A') }, ['c'], ['a'], 'blue'); const s = R.turn, o = 1 - s; const c = field(R, s, 'c'); if (bond) field(R, s, 'h'); const a = field(R, o, 'a'); fileN(R, o, 6); const fz = give(R, o, 'fz', 'file'); const f0 = R.P[o].file.splice(R.P[o].file.indexOf(fz), 1)[0]; R.P[o].file.push(fz); return { R, s, o, c, a, fz, named }; };
  let r = run('FILETARGET'); const d0 = own(r.R, r.s, 'deck'), od = own(r.R, r.o, 'deck'), of = own(r.R, r.o, 'file'); decl(r.R, r.s, r.c); eq(own(r.R, r.s, 'deck'), d0 - 1, '내 덱 위 1장 리무브(코스트)'); let q = req(r.R); eq(q.kind, 'text', '카드명 지정'); ans(r.R, 'FILETARGET'); q = req(r.R); ok(q && q.kind === 'pick', '캐릭터 선택(AP+2000)'); ok(has(r.R, r.o, 'rem', r.fz), '상대 FILE 맨 위 카드 리무브'); eq(own(r.R, r.o, 'file'), of, 'FILE 장수 유지(-1+1)'); eq(own(r.R, r.o, 'deck'), od - 1, '상대 덱 -1'); const nf = r.R.P[r.o].file[r.R.P[r.o].file.length - 1]; ok(!r.R.cards[nf].up, '새 FILE 맨 위는 뒷면'); ok(!JSON.stringify(S.view(r.R, r.s).P[r.o].fileUp).includes(String(nf)), '내 화면에 새 FILE 카드 정보 없음'); rej(r.R, [999999]); const ap0 = S.ap(r.R, r.a); ans(r.R, [r.a]); pump(r.R); eq(S.ap(r.R, r.a), ap0 + 2000, 'AP+2000'); ok(declErr(r.R, r.s, r.c), '턴 1회'); endTurn(r.R); auto(r.R); eq(S.ap(r.R, r.a), ap0, '턴 종료 시 해제');
  r = run('X'); decl(r.R, r.s, r.c); ans(r.R, 'ZZZNOPE'); pump(r.R); ok(!req(r.R), '다른 카드명: AP 효과 없음'); ok(has(r.R, r.o, 'rem', r.fz), '그래도 FILE 카드는 리무브'); r = run('X', false); ok(chk(r.R, r.s, r.c), '[服部平次] 없음: 불가'); });
t('id_0955', '【FILE⑥】 선언(슬립): 내 리무브 에리어의 Lv4 [少年探偵団](이름이 서로 다른) 2장까지 등장 → 내 FILE 위 1장 리무브', () => {
  const run = (file = 6) => { const R = mk({ c: rc('id_0955'), d1: dm('D1', { trait: '少年探偵団', lv: '4' }), d1b: dm('D1', { trait: '少年探偵団', lv: '4' }), d2: dm('D2', { trait: '少年探偵団', lv: '4' }), d3: dm('D3', { trait: '少年探偵団', lv: '3' }), z: dm('Z', { trait: '高校生', lv: '4' }) }, ['c'], ['c'], 'blue'); const s = R.turn; fileN(R, s, file); const c = field(R, s, 'c'); const d1 = rem(R, s, 'd1'), d1b = rem(R, s, 'd1b'), d2 = rem(R, s, 'd2'), d3 = rem(R, s, 'd3'), z = rem(R, s, 'z'); return { R, s, c, d1, d1b, d2, d3, z }; };
  let r = run(); const f0 = own(r.R, r.s, 'file'), ftop = r.R.P[r.s].file[f0 - 1]; decl(r.R, r.s, r.c); eq(r.R.cards[r.c].st, 's', '슬립'); const q = req(r.R); ok(q.max === 2 && q.distinct && q.sel.includes(r.d1) && q.sel.includes(r.d2) && !q.sel.includes(r.d3) && !q.sel.includes(r.z), 'Lv4 [少年探偵団] 만, 이름 달라야 함'); rej(r.R, [r.d1, r.d1b]); rej(r.R, [r.d3]); ans(r.R, [r.d1, r.d2]); pump(r.R); ok(has(r.R, r.s, 'field', r.d1) && has(r.R, r.s, 'field', r.d2), '2장 등장'); eq(own(r.R, r.s, 'file'), f0 - 1, 'FILE 위 1장 리무브'); ok(has(r.R, r.s, 'rem', ftop), '그 카드는 리무브 에리어'); r.R.cards[r.c].st = 'a'; ok(declErr(r.R, r.s, r.c), 'FILE 5장이 되어 재선언 불가');
  r = run(); decl(r.R, r.s, r.c); ans(r.R, []); eq(own(r.R, r.s, 'file'), 5, '0장 등장해도 FILE 리무브는 함'); r = run(5); ok(chk(r.R, r.s, r.c), 'FILE 5장: 불가'); });
